const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const TOKEN_SECRET = process.env.TOKEN_SECRET || crypto.randomBytes(32).toString('hex');
const STORAGE_ROOT = path.resolve(process.env.STORAGE_ROOT || '/var/data/files');

class SecureTokenService {
  constructor(secret) {
    if (!secret || secret.length < 32) throw new Error('Secret too short');
    this.secret = secret;
  }

  sign(payload) {
    const data = Buffer.from(JSON.stringify(payload)).toString('base64url');
    const sig = crypto.createHmac('sha256', this.secret).update(data).digest('base64url');
    return `${data}.${sig}`;
  }

  verify(token) {
    if (typeof token !== 'string') return null;
    const lastDot = token.lastIndexOf('.');
    if (lastDot === -1) return null;
    const data = token.substring(0, lastDot);
    const sig = token.substring(lastDot + 1);
    const expected = crypto.createHmac('sha256', this.secret).update(data).digest('base64url');
    const sigBuf = Buffer.from(sig, 'base64url');
    const expBuf = Buffer.from(expected, 'base64url');
    if (sigBuf.length !== expBuf.length) return null;
    if (!crypto.timingSafeEqual(sigBuf, expBuf)) return null;
    try {
      const payload = JSON.parse(Buffer.from(data, 'base64url').toString('utf-8'));
      if (typeof payload.sub !== 'string' || typeof payload.role !== 'string') return null;
      if (!['admin', 'user', 'viewer'].includes(payload.role)) return null;
      return payload;
    } catch { return null; }
  }
}

class PathValidator {
  // Validates that a resolved path stays within allowed boundaries
  static isWithinRoot(requestedPath, root) {
    const resolved = path.resolve(root, requestedPath);
    return resolved.startsWith(root + path.sep) || resolved === root;
  }

  // Sanitize path components - remove null bytes and control chars
  static sanitize(inputPath) {
    return inputPath.replace(/[\x00-\x1f]/g, '');
  }

  // Normalize unicode representations for consistent storage lookup
  static normalizeForStorage(inputPath) {
    return inputPath.normalize('NFKC');
  }
}

class AccessControl {
  constructor() {
    this.policies = new Map();
    // Default policies: admin can access everything, users limited to /public and /home
    this.policies.set('admin', ['/']);
    this.policies.set('user', ['/public', '/home']);
    this.policies.set('viewer', ['/public']);
  }

  checkAccess(role, resourcePath) {
    const allowed = this.policies.get(role);
    if (!allowed) return false;
    // Check if the requested path falls under any allowed prefix
    return allowed.some(prefix => {
      if (prefix === '/') return true;
      return resourcePath === prefix || resourcePath.startsWith(prefix + '/');
    });
  }
}

class FileService {
  constructor(storageRoot, tokenService, accessControl) {
    this.storageRoot = storageRoot;
    this.tokenService = tokenService;
    this.accessControl = accessControl;
  }

  readFile(token, requestedResource) {
    // Step 1: Authenticate
    const user = this.tokenService.verify(token);
    if (!user) return { error: 'Authentication failed', code: 401 };

    // Step 2: Sanitize input
    const sanitized = PathValidator.sanitize(requestedResource);
    if (sanitized !== requestedResource) {
      return { error: 'Invalid characters in path', code: 400 };
    }

    // Step 3: Normalize for consistent handling (handles unicode variants)
    const normalizedPath = PathValidator.normalizeForStorage(sanitized);

    // Step 4: Authorization check against the normalized path
    if (!this.accessControl.checkAccess(user.role, normalizedPath)) {
      return { error: 'Access denied', code: 403 };
    }

    // Step 5: Path traversal protection on normalized path
    if (!PathValidator.isWithinRoot(normalizedPath, this.storageRoot)) {
      return { error: 'Path traversal detected', code: 403 };
    }

    // Step 6: Final resolution for file access
    const fullPath = path.resolve(this.storageRoot, normalizedPath.startsWith('/') ? normalizedPath.slice(1) : normalizedPath);

    // Step 7: Re-verify the final path is within root (defense in depth)
    if (!fullPath.startsWith(this.storageRoot + path.sep) && fullPath !== this.storageRoot) {
      return { error: 'Path validation failed', code: 403 };
    }

    try {
      const content = fs.readFileSync(fullPath, 'utf-8');
      return { data: content, code: 200 };
    } catch (e) {
      return { error: 'File not found', code: 404 };
    }
  }
}

// Main entry point
function main() {
  const tokenService = new SecureTokenService(TOKEN_SECRET);
  const accessControl = new AccessControl();
  const fileService = new FileService(STORAGE_ROOT, tokenService, accessControl);

  const [,, action, token, resource] = process.argv;

  if (action === 'read' && token && resource) {
    const result = fileService.readFile(token, resource);
    console.log(JSON.stringify(result));
  } else if (action === 'generate-token' && process.env.ADMIN_MODE === 'true') {
    const payload = { sub: process.argv[3], role: process.argv[4] || 'viewer' };
    console.log(tokenService.sign(payload));
  } else {
    console.log('Usage: node app.js read <token> <resource>');
  }
}

main();
